interface.signature:
interface DeviceProfile {
  id: string;
  brand: 'oppo' | 'oneplus' | 'realme';
  name: string;
  codename: string;
  chipset: string;
  chipsetName: string;
  status: 'tested' | 'beta' | 'coming';
  authMethod: 'oppo_vip' | null;
  presetId: string | null;
  firehose?: {
    programmerUrl: string;
    digestUrl: string;
    signatureUrl: string;
  };
}
